import { Button, Text, Badge, makeStyles, tokens } from '@fluentui/react-components'
import { NoteRegular } from '@fluentui/react-icons'
import type { Card } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'

const useStyles = makeStyles({
  card: {
    backgroundColor: tokens.colorNeutralBackground1,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalS,
    paddingLeft: tokens.spacingHorizontalM,
    paddingRight: tokens.spacingHorizontalS,
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: tokens.spacingHorizontalS,
    boxShadow: tokens.shadow2,
    cursor: 'default',
  },
  body: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
    flex: 1,
    minWidth: 0,
  },
  meta: {
    display: 'flex',
    alignItems: 'center',
    gap: tokens.spacingHorizontalXS,
  },
})

interface CardItemProps {
  card: Card
  callerRole: BoardRole
  onEdit: (card: Card) => void
  onDelete: (card: Card) => void
}

export default function CardItem({ card, callerRole, onEdit, onDelete }: CardItemProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'

  return (
    <article className={styles.card}>
      <div className={styles.body}>
        <Text>{card.title}</Text>
        <div className={styles.meta}>
          {card.dueDate && (
            <Badge appearance="outline" size="small">
              {card.dueDate}
            </Badge>
          )}
          {card.description && (
            <span role="img" aria-label="has description">
              <NoteRegular fontSize={14} aria-hidden="true" />
            </span>
          )}
        </div>
      </div>
      {canModify && (
        <>
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Edit card ${card.title}`}
            onClick={() => onEdit(card)}
          >
            Edit
          </Button>
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete card ${card.title}`}
            onClick={() => onDelete(card)}
          >
            Delete card
          </Button>
        </>
      )}
    </article>
  )
}

import { useState } from 'react'
import {
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
  Field,
  Input,
  MessageBar,
  Textarea,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import type { Card } from '../../hooks/useBoard'
import { useUpdateCard } from '../../hooks/useUpdateCard'
import { useDeleteCard } from '../../hooks/useDeleteCard'

const useStyles = makeStyles({
  fields: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalM,
  },
})

interface CardDetailDialogProps {
  card: Card
  open: boolean
  onClose: () => void
  initialConfirmDelete?: boolean
}

export default function CardDetailDialog({ card, open, onClose, initialConfirmDelete }: CardDetailDialogProps) {
  const styles = useStyles()
  const [title, setTitle] = useState(card.title)
  const [description, setDescription] = useState(card.description ?? '')
  const [dueDate, setDueDate] = useState(card.dueDate ?? '')
  const [clearDueDate, setClearDueDate] = useState(false)
  const [confirmDelete, setConfirmDelete] = useState(initialConfirmDelete ?? false)

  const updateCard = useUpdateCard()
  const deleteCard = useDeleteCard()

  const handleSave = () => {
    updateCard.mutate(
      {
        boardId: card.boardId,
        cardId: card.id,
        title,
        description: description || null,
        clearDueDate,
        dueDate: clearDueDate ? null : (dueDate || null),
      },
      { onSuccess: onClose },
    )
  }

  const handleDelete = () => {
    deleteCard.mutate(
      { boardId: card.boardId, cardId: card.id },
      { onSuccess: onClose },
    )
  }

  const isMutating = updateCard.isPending || deleteCard.isPending
  const hasError = updateCard.isError || deleteCard.isError

  if (confirmDelete) {
    return (
      <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
        <DialogSurface>
          <DialogBody>
            <DialogTitle>Delete card?</DialogTitle>
            <DialogContent>
              This will permanently delete "{card.title}". This action cannot be undone.
            </DialogContent>
            <DialogActions>
              <Button
                appearance="primary"
                onClick={handleDelete}
                disabled={isMutating}
              >
                Confirm
              </Button>
              <Button appearance="subtle" onClick={() => setConfirmDelete(false)}>
                Cancel
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>
    )
  }

  return (
    <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>Edit card</DialogTitle>
          <DialogContent>
            {hasError && (
              <MessageBar role="alert" intent="error">
                Failed to save changes. Please try again.
              </MessageBar>
            )}
            <div className={styles.fields}>
              <Field label="Title" required>
                <Input
                  aria-label="Title"
                  value={title}
                  onChange={(_, d) => setTitle(d.value)}
                />
              </Field>
              <Field label="Description">
                <Textarea
                  aria-label="Description"
                  value={description}
                  onChange={(_, d) => setDescription(d.value)}
                />
              </Field>
              <Field label="Due date">
                <Input
                  aria-label="Due date"
                  type="date"
                  value={clearDueDate ? '' : dueDate}
                  onChange={(_, d) => setDueDate(d.value)}
                  disabled={clearDueDate}
                />
              </Field>
              <Checkbox
                label="Clear due date"
                checked={clearDueDate}
                onChange={(_, d) => setClearDueDate(!!d.checked)}
              />
            </div>
          </DialogContent>
          <DialogActions>
            <Button
              appearance="primary"
              onClick={handleSave}
              disabled={isMutating}
            >
              Save
            </Button>
            <Button
              appearance="outline"
              onClick={() => setConfirmDelete(true)}
              disabled={isMutating}
            >
              Delete card
            </Button>
            <DialogTrigger disableButtonEnhancement>
              <Button appearance="subtle">
                Cancel
              </Button>
            </DialogTrigger>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  )
}

import { useState } from 'react'
import { Button, Title2, makeStyles, tokens } from '@fluentui/react-components'
import type { Card, Lane as LaneData } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'
import CardItem from './CardItem'
import AddCardForm from './AddCardForm'
import CardDetailDialog from './CardDetailDialog'

const useStyles = makeStyles({
  lane: {
    minWidth: '260px',
    maxWidth: '320px',
    backgroundColor: tokens.colorNeutralBackground2,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalM,
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  cards: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
  emptySlot: {
    height: '40px',
    borderRadius: tokens.borderRadiusMedium,
    border: `1px dashed ${tokens.colorNeutralStroke2}`,
  },
})

interface LaneProps {
  lane: LaneData
  callerRole: BoardRole
  onDelete: (boardId: string, laneId: string) => void
}

export default function Lane({ lane, callerRole, onDelete }: LaneProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'
  const [editingCard, setEditingCard] = useState<Card | null>(null)
  const [deletingCard, setDeletingCard] = useState<Card | null>(null)

  const sortedCards = [...lane.cards].sort((a, b) => a.position - b.position)

  return (
    <section className={styles.lane} aria-label={`Lane: ${lane.name}`}>
      <div className={styles.header}>
        <Title2 as="h2">{lane.name}</Title2>
        {canModify && (
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete lane ${lane.name}`}
            onClick={() => onDelete(lane.boardId, lane.id)}
          >
            Delete
          </Button>
        )}
      </div>
      <div className={styles.cards}>
        {sortedCards.length === 0 && !canModify && (
          <div className={styles.emptySlot} aria-hidden="true" />
        )}
        {sortedCards.map((card) => (
          <CardItem
            key={card.id}
            card={card}
            callerRole={callerRole}
            onEdit={setEditingCard}
            onDelete={setDeletingCard}
          />
        ))}
      </div>
      {canModify && <AddCardForm boardId={lane.boardId} laneId={lane.id} />}
      {editingCard && (
        <CardDetailDialog
          card={editingCard}
          open={true}
          onClose={() => setEditingCard(null)}
        />
      )}
      {deletingCard && (
        <CardDetailDialog
          card={deletingCard}
          open={true}
          onClose={() => setDeletingCard(null)}
          initialConfirmDelete={true}
        />
      )}
    </section>
  )
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import type { ApiError } from './useBoards'
import type { Card } from './useBoard'

interface UpdateCardVars {
  boardId: string
  cardId: string
  title?: string | null
  description?: string | null
  clearDueDate: boolean
  dueDate?: string | null
}

async function updateCard(vars: UpdateCardVars): Promise<Card> {
  const response = await fetch(`/api/v1/boards/${vars.boardId}/cards/${vars.cardId}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      title: vars.title ?? null,
      description: vars.description ?? null,
      clearDueDate: vars.clearDueDate,
      dueDate: vars.dueDate ?? null,
    }),
  })
  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw { status: response.status, code: body.code, title: body.title } as ApiError
  }
  return response.json() as Promise<Card>
}

export function useUpdateCard() {
  const queryClient = useQueryClient()
  return useMutation<Card, ApiError, UpdateCardVars>({
    mutationFn: updateCard,
    onSettled: (_data, _error, { boardId }) =>
      queryClient.invalidateQueries({ queryKey: ['boards', boardId] }),
    retry: false,
  })
}

using Kanban.Business.Interfaces;
using Kanban.Contracts;

namespace Kanban.Api.Endpoints;

public static class CardEndpoints
{
    public static void Map(IEndpointRouteBuilder routes)
    {
        var cards = routes.MapGroup("/boards/{boardId:guid}");

        cards.MapPost("lanes/{laneId:guid}/cards",
            async (Guid boardId, Guid laneId, CreateCardRequest request, ICardService cardService) =>
            {
                var card = await cardService.CreateAsync(boardId, laneId, request);
                return Results.Created($"/api/v1/boards/{boardId}/cards/{card.Id}", card);
            })
            .WithName("CreateCard")
            .WithSummary("Create a card in a lane")
            .Produces<CardDto>(201)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        cards.MapPatch("cards/{cardId:guid}",
            async (Guid boardId, Guid cardId, UpdateCardRequest request, ICardService cardService) =>
                Results.Ok(await cardService.UpdateAsync(boardId, cardId, request)))
            .WithName("UpdateCard")
            .WithSummary("Update a card's fields")
            .Produces<CardDto>(200)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        cards.MapDelete("cards/{cardId:guid}",
            async (Guid boardId, Guid cardId, ICardService cardService) =>
            {
                await cardService.DeleteAsync(boardId, cardId);
                return Results.NoContent();
            })
            .WithName("DeleteCard")
            .WithSummary("Delete a card")
            .Produces(204)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .RequireRateLimiting("mutating");

        cards.MapPost("cards/{cardId:guid}/move",
            async (Guid boardId, Guid cardId, MoveCardRequest request, ICardService cardService) =>
                Results.Ok(await cardService.MoveAsync(boardId, cardId, request)))
            .WithName("MoveCard")
            .WithSummary("Move a card to a new lane/position")
            .Produces<CardDto>(200)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(409)
            .RequireRateLimiting("mutating");
    }
}

